#include <Arduino.h>
#include <Servo.h>
Servo servo1;
Servo servo2;
Servo servo3;

void setup();
void loop();
void setup() {
  pinMode(2, OUTPUT);  
  pinMode(3, OUTPUT);  
  pinMode(4, OUTPUT);  
  pinMode(5, OUTPUT);  
  pinMode(6, OUTPUT);  
  pinMode(7, OUTPUT);  
  pinMode(8, OUTPUT);  
  pinMode(9, OUTPUT);  
  pinMode(10, OUTPUT);  
  servo1.attach(11);    
  servo2.attach(12);   
  servo3.attach(13);   
  servo3.write(0);     
}
void loop() {
  int pot1Value = analogRead(A3);  
  int pot2Value = analogRead(A4);  
  int red = map(pot1Value, 0, 1023, 0, 255);
  int green = map(pot2Value, 0, 1023, 0, 255);
  int blue = 0;  
  analogWrite(2, red);    
  analogWrite(3, green);  
  analogWrite(4, blue);   
  analogWrite(5, red);    
  analogWrite(6, green);  
  analogWrite(7, blue);   
  analogWrite(8, red);    
  analogWrite(9, green);  
  analogWrite(10, blue);   
  int servo1Pos = map(pot1Value, 0, 1023, 0, 180);
  int servo2Pos = map(pot2Value, 0, 1023, 0, 180);
  servo1.write(servo1Pos);
  servo2.write(servo2Pos);
  static unsigned long lastToggleTime = 0;
  static int servo3Pos = 0;
  if (millis() - lastToggleTime >= 2000) {
    servo3Pos = (servo3Pos == 0) ? 180 : 0;
    servo3.write(servo3Pos);
    lastToggleTime = millis();
  }
  delay(100);  
}
